#define __LL_ATON_STAI_CHECK_NETWORK_INTERFACE(nn_interface_ptr, ctx)                                                  \
  do                                                                                                                   \
  {                                                                                                                    \
    if ((nn_interface_ptr) != &NN_Interface_dlfut)                                                     \
      __LL_ATON_STAI_SET_1ST_CTX_ERROR_AND_RETURN((ctx), STAI_ERROR_NETWORK_INVALID_CONTEXT_HANDLE);                   \
